1	const LOCODE = /^[A-Z]{2}[A-Z2-9]{3}$/;
2	
3	export function normaliseLocode(input: string): string {
4	  return input.trim().toUpperCase();
5	}
6	
7	export function isValidLocode(input: string): boolean {
8	  return LOCODE.test(normaliseLocode(input));
9	}
10	
11	export function countryOf(locode: string): string {
12	  const code = normaliseLocode(locode);
13	  if (!LOCODE.test(code)) {
14	    throw new RangeError(`not a UN/LOCODE: ${locode}`);
15	  }
16	  return code.slice(0, 2);
17	}
